    status: 'draft',
    fb_post_id: '',
    ig_post_id: '',
    optimization_version: '0',
    created_at: now
  }
}));

// 將已使用的主題標記為 used
const posts = $('3·解析貼文').all().map(i => i.json);
const topicIds = [...new Set(posts.map(p => p.topic_id).filter(Boolean))];

return topicIds.map(id => ({ json: { topic_id: id, status: 'used' } }));

// 依內容自動產生封面圖（由 AutoPost 網站決定版型並渲染成配圖）
const BASE = 'https://auto-post-renew.vercel.app';
const req = (($('3·驗證請求').first() || {}).json) || {};
const brand = (($('3·讀取品牌').first() || {}).json) || {};
const topicTitle = req.topic_title || '';
const brandName = brand.brand_name || '';
const results = [];
for (const item of $input.all()) {
  const post = item.json;
  const title = post.topic_title || topicTitle || '';
  const caption = String(post.caption || '').slice(0, 420);
  const qs = new URLSearchParams();
  if (title) qs.set('title', title);
  if (caption) qs.set('caption', caption);
  if (brandName) qs.set('brand', brandName);
  const image_url = BASE + '/api/cover?' + qs.toString();
  results.push({ json: { ...post, image_url, topic_title: title } });
}
return results;

// 拆兩列：一篇主題 → 一篇 FB + 一篇 IG
const out = [];
for (const item of $input.all()) {
  const base = item.json;
  const ts = Date.now();
  const rnd = Math.random().toString(36).slice(2, 7);
  for (const plat of ['facebook', 'instagram']) {
    out.push({ json: {
      ...base,
      post_id: base.post_id || `post-${ts}-${plat[0]}-${rnd}`,
      platform: plat
    } });
  }
}
return out;

