  }
}];

const brand = $('5·讀取品牌').first().json;
const posts = $('5·讀取已發佈貼文').all().map(i => i.json);

if (!brand.meta_access_token) {
  throw new Error('品牌尚未設定 Meta Access Token');
}

const results = [];
for (const post of posts) {
  if (post.fb_post_id) {
    results.push({
      post_id: post.post_id,
      platform_post_id: post.fb_post_id,
      platform: 'facebook',
      access_token: brand.meta_access_token
    });
  }
  if (post.ig_post_id) {
    results.push({
      post_id: post.post_id,
      platform_post_id: post.ig_post_id,
      platform: 'instagram',
      access_token: brand.meta_access_token
    });
  }
}

return results.map(r => ({ json: r }));

const brandId = $('5·驗證請求').first().json.brand_id;
const items = $input.all();
const now = new Date().toISOString();

return items.map((item, i) => {
  const data = item.json;
  const likes = data.likes?.summary?.total_count || data.data?.[0]?.values?.[0]?.value || 0;
  const comments = data.comments?.summary?.total_count || data.data?.[1]?.values?.[0]?.value || 0;
  const shares = data.shares?.count || data.data?.[2]?.values?.[0]?.value || 0;
  const reach = data.insights?.data?.[0]?.values?.[0]?.value || data.data?.[3]?.values?.[0]?.value || 0;
  const totalInteractions = likes + comments + shares;
  const engagementRate = reach > 0 ? ((totalInteractions / reach) * 100).toFixed(2) : '0';

  return {
    json: {
      analytics_id: `ana-${Date.now()}-${i}`,
      brand_id: brandId,
      post_id: $('5·展開貼文清單').all()[i]?.json?.post_id || '',
      platform: $('5·展開貼文清單').all()[i]?.json?.platform || '',
      likes: String(likes),
      comments: String(comments),
      shares: String(shares),
      reach: String(reach),
      engagement_rate: engagementRate,
      collected_at: now
    }
  };
});

const apiKey = $input.first().json.body.api_key;
